        m: [["Anna besucht seine Oma.", "Anna besucht ihre Oma.", "Pemiliknya Anna (perempuan): ihr."], ["Ich besuche mein Vater.", "Ich besuche meinen Vater.", "Akusatif maskulin: meinen."], ["Das ist mein Mutter.", "Das ist meine Mutter.", "die Mutter: meine."]],
